    16          /**
    17           * @class TLVRecord
    18           * A wrapper class for a Type-Length-Value (TLV) record. This class does not create or modify TLV records, but rather
    19           * serves as a wrapper and provides useful methods for retrieving data from them. This class has several abstract methods
    20           * that should be implemented in derived classes. These methods are for record length value calculation (the 'L' in TLV)
    21           * which is implemented differently in different protocols
    22           */
    23          template<typename TRecType, typename TRecLen>
    24          class TLVRecord
    25          {
    26          protected:
    27
    28                  /** A struct representing the TLV construct */
    29                  struct TLVRawData
    30                  {
    31                          /** Record type */
    32                          TRecType recordType;
    33                          /** Record length in bytes */
    34                          TRecLen recordLen;
    35                          /** Record value (variable size) */
    36                          uint8_t recordValue[];
    37                  };
    38
    39                  TLVRawData* m_Data;
    40
    41          public:
    42
    43                  /**
    44                   * A c'tor for this class that gets a pointer to the TLV record raw data (byte array)
    45                   * @param[in] recordRawData A pointer to the TLV record raw data
    46                   */
    47                  TLVRecord(uint8_t* recordRawData)
    48                  {
    49                          assign(recordRawData);
    50                  }
    51
    52                  /**
    53                   * A copy c'tor for this class. This copy c'tor doesn't copy the TLV data, but only the pointer to it,
    54                   * which means that after calling it both the old and the new instance will point to the same TLV raw data
    55                   * @param[in] other The TLVRecord instance to copy from
    56                   */
    57                  TLVRecord(const TLVRecord& other)
    58                  {
    59                          m_Data = other.m_Data;
    60                  }
    61
    62                  /**
    63                   * A d'tor for this class, currently does nothing
    64                   */
    65                  virtual ~TLVRecord() { }
    66
    67                  /**
    68                   * Assign a pointer to the TLV record raw data (byte array)
    69                   * @param[in] recordRawData A pointer to the TLV record raw data
    70                   */
    71                  void assign(uint8_t* recordRawData)
    72                  {
    73                          if(recordRawData == NULL)
    74                                  m_Data = NULL;
    75                          else
    76                                  m_Data = (TLVRawData*)recordRawData;
    77                  }
    78
    79                  /**
    80                   * Overload of the assignment operator. This operator doesn't copy the TLV data, but rather copies the pointer to it,
    81                   * which means that after calling it both the old and the new instance will point to the same TLV raw data
    82                   * @param[in] other The TLVRecord instance to assign
    83                   */
    84                  TLVRecord& operator=(const TLVRecord& other)
    85                  {
    86                          m_Data = other.m_Data;
    87                          return *this;
    88                  }
    89
    90                  /**
    91                   * Overload of the equality operator. Two record are equal if both of them point to the same data, or if they point
    92                   * to different data but their total size is equal and the raw data they both contain is similar.
    93                   * @param[in] rhs The object to compare to
    94                   * @return True if both objects are equal, false otherwise
    95                   */
    96                  bool operator==(const TLVRecord& rhs) const
    97                  {
    98                          if (m_Data == rhs.m_Data)
    99                                  return true;
   100
   101                          if (getTotalSize() != rhs.getTotalSize())
   102                                  return false;
   103
   104                          if (isNull() || ((TLVRecord&)rhs).isNull())
   105                                  return false;
   106
   107                          return (memcmp(m_Data, rhs.m_Data, getTotalSize()) == 0);
   108                  }
   109
   110                  /**
   111                   * Overload of the not equal operator.
   112                   * @param[in] rhs The object to compare to
   113                   * @return True if objects are not equal, false otherwise
   114                   */
   115                  bool operator!=(const TLVRecord& rhs) const
   116                  {
   117                          return !operator==(rhs);
   118                  }
   119
   120                  /**
   121                   * @return The type field of the record (the 'T' in __Type__-Length-Value)
   122                   */
   123                  TRecType getType() const {
   124                          if (m_Data == nullptr)
   125                                  return 0;
   126
   127                          return m_Data->recordType;
   128                  }
   129
   130                  /**
   131                   * @return A pointer to the value of the record as byte array (the 'V' in Type-Length- __Value__)
   132                   */
   133                  uint8_t* getValue() const {
   134                          if (m_Data == nullptr)
   135                                  return nullptr;
   136
   137                          return m_Data->recordValue;
   138                  }
   139
   140                  /**
   141                   * @return True if the TLV record raw data is NULL, false otherwise
   142                   */
   143                  bool isNull() const { return (m_Data == nullptr); }
   144
   145                  /**
   146                   * @return True if the TLV record raw data is not NULL, false otherwise
   147                   */
   148                  bool isNotNull() const { return (m_Data != nullptr); }
   149
   150                  /**
   151                   * @return A pointer to the TLV record raw data byte stream
   152                   */
   153                  uint8_t* getRecordBasePtr() const { return (uint8_t*)m_Data; }
   154
   155                  /**
   156                   * Free the memory of the TLV record raw data
   157                   */
   158                  void purgeRecordData() { if (!isNull()) delete [] m_Data; }
   159
   160                  /**
   161                   * A templated method to retrieve the record data as a certain type T. For example, if record data is 4B long
   162                   * (integer) then this method should be used as getValueAs<int>() and it will return the record data as an integer.<BR>
   163                   * Notice this return value is a copy of the data, not a pointer to the actual data
   164                   * @param[in] offset The offset in the record data to start reading the value from. Useful for cases when you want
   165                   * to read some of the data that doesn't start at offset 0. This is an optional parameter and the default value
   166                   * is 0, meaning start reading the value at the beginning of the record data
   167                   * @return The record data as type T
   168                   */
   169                  template<typename T>
   170                  T getValueAs(size_t offset = 0) const
   171                  {
   172                          if (getDataSize() - offset < sizeof(T))
   173                                  return 0;
   174
   175                          T result;
   176                          memcpy(&result, m_Data->recordValue + offset, sizeof(T));
   177                          return result;
   178                  }
   179
   180                  /**
   181                   * A templated method to copy data of type T into the TLV record data. For example: if record data is 4[Bytes] long use
   182                   * this method with \<int\> to set an integer value into the record data: setValue<int>(num)
   183                   * @param[in] newValue The value of type T to copy to the record data
   184                   * @param[in] valueOffset An optional parameter that specifies where to start setting the record data (default set to 0). For example:
   185                   * if record data is 20 bytes long and you only need to set the 4 last bytes as integer then use this method like this:
   186                   * setValue<int>(num, 16)
   187                   * @return True if value was set successfully or false if the size of T is larger than the record data size
   188                   */
   189                  template<typename T>
   190                  bool setValue(T newValue, int valueOffset = 0)
   191                  {
   192                          if (getDataSize() < sizeof(T))
   193                                  return false;
   194
   195                          memcpy(m_Data->recordValue + valueOffset, &newValue, sizeof(T));
   196                          return true;
   197                  }
   198
   199                  /**
   200                   * @return The total size of the TLV record (in bytes)
   201                   */
   202                  virtual size_t getTotalSize() const = 0;
   203
   204                  /**
   205                   * @return The size of the record value (meaning the size of the 'V' part in TLV)
   206                   */
   207                  virtual size_t getDataSize() const = 0;
   208          };
